// Generic minimize template - find minimum mid where feasible(mid) is true
// Concrete example: Koko Eating Bananas
function minEatingSpeed(piles, h) {
  // feasible(speed): can Koko eat all piles in h hours at this speed?
  function feasible(speed) {
    let hours = 0;
    for (const pile of piles) {
      hours += Math.ceil(pile / speed);
    }
    return hours <= h;
  }

  // lo: minimum possible answer (eat at least 1)
  // hi: maximum needed answer (eat largest pile in one hour)
  let lo = 1, hi = Math.max(...piles);
  let ans = hi; // start with worst-case answer

  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (feasible(mid)) {
      ans = mid;    // mid works - record it, try smaller
      hi = mid - 1;
    } else {
      lo = mid + 1; // mid doesn't work - need larger
    }
  }

  return ans;
}
